import { t } from "./i18n";
import { ImagePrepError } from "./image";
import type { RoomType } from "./types";

export interface SampleImage {
  url: string;
  roomType: RoomType;
  /** Key into the `samples` dictionary. */
  labelKey: "bathroom" | "stairs";
}

// Original illustrations generated by client/scripts/generate-samples.mjs.
export const SAMPLE_IMAGES: SampleImage[] = [
  { url: "/samples/bathroom-wet-floor.jpg", roomType: "bathroom", labelKey: "bathroom" },
  { url: "/samples/stairs-no-handrail.jpg", roomType: "stairs", labelKey: "stairs" },
];

export async function fetchSample(sample: SampleImage): Promise<Blob> {
  const res = await fetch(sample.url);
  if (!res.ok) throw new ImagePrepError(t().errors.sampleLoad);
  return res.blob();
}
